<?php $view=in_array($_GET['view']??'week',['day','week','month'],true)?$_GET['view']:'week';$anchor=new DateTimeImmutable($_GET['date']??date('Y-m-d'));if($view==='day'){$from=$through=$anchor->format('Y-m-d');}elseif($view==='month'){$from=$anchor->modify('first day of this month')->format('Y-m-d');$through=$anchor->modify('last day of this month')->format('Y-m-d');}else{$from=$anchor->modify('monday this week')->format('Y-m-d');$through=$anchor->modify('sunday this week')->format('Y-m-d');}$calendarShifts=array_values(array_filter($shifts,fn($shift)=>$shift['shift_date']>=$from&&$shift['shift_date']<=$through&&$shift['status']!=='cancelled'));$grouped=[];foreach($calendarShifts as $shift)$grouped[$shift['shift_date']][]=$shift;?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schedule Views · Atlas</title><link rel="stylesheet" href="<?=esc(url_for('assets/app.css'))?>"><style>@media print{.sidebar,.standalone-menu,.schedule-filters,.page-header .button{display:none!important}.standalone-workspace{margin:0!important;padding:0!important}.panel{break-inside:avoid;box-shadow:none;border:1px solid #bbb}}</style></head><body class="standalone-with-nav"><?=standaloneSidebar($navGroups,'schedule-calendar',$admin,$org,$user,$location)?><main class="page-wrap standalone-workspace"><header class="page-header"><div><p class="eyebrow">SCHEDULE VIEWS</p><h1><?=esc(ucfirst($view))?> schedule</h1><p><?=esc(date('M j, Y',strtotime($from)).($through!==$from?' through '.date('M j, Y',strtotime($through)):''))?></p></div><button class="button secondary" onclick="window.print()">Print</button></header><form method="get" class="schedule-filters"><input type="hidden" name="route" value="schedule-calendar"><label>View<select name="view"><option value="day" <?=$view==='day'?'selected':''?>>Day</option><option value="week" <?=$view==='week'?'selected':''?>>Week</option><option value="month" <?=$view==='month'?'selected':''?>>Month</option></select></label><label>Date<input type="date" name="date" value="<?=$anchor->format('Y-m-d')?>"></label><button class="button primary">Apply</button></form><section class="planning-grid"><?php for($cursor=new DateTimeImmutable($from);$cursor<=new DateTimeImmutable($through);$cursor=$cursor->modify('+1 day')):$date=$cursor->format('Y-m-d');if($view==='month'&&!isset($grouped[$date]))continue;?><article class="panel"><h2><?=esc($cursor->format('D, M j'))?></h2><?php foreach($grouped[$date]??[] as $shift):?><div class="planning-row"><span><strong><?=esc(date('g:i A',strtotime($shift['starts_at'])).'–'.date('g:i A',strtotime($shift['ends_at'])))?></strong><small><?=esc($shift['department_name'].' · '.($shift['assigned_name']?:'Open shift'))?></small></span><b class="state-pill <?=$shift['status']==='open'?'gap':'covered'?>"><?=esc(ucfirst($shift['status']))?></b></div><?php endforeach;?><?php if(empty($grouped[$date])):?><div class="inline-empty"><strong>No scheduled shifts</strong></div><?php endif;?></article><?php endfor;?></section></main></body></html>
